use std::thread;

fn main() {
    println!("main: starting a worker");
    let handle = thread::spawn(|| {
        println!("worker: hello from another thread");
    });
    handle.join().unwrap();
    println!("main: the worker has finished");
}

// Output:
// main: starting a worker
// worker: hello from another thread
// main: the worker has finished

use std::thread;

fn main() {
    let handle = thread::spawn(|| {
        let mut total = 0;
        for n in 1..=100 {
            total += n;
        }
        total
    });
    let total = handle.join().unwrap();
    println!("sum of 1..=100 is {total}");
}

// Output:
// sum of 1..=100 is 5050

