use std::thread;

fn main() {
    let words = vec![String::from("alpha"), String::from("beta"), String::from("gamma")];
    let mut handles = Vec::new();
    for word in words {
        let handle = thread::spawn(move || {
            let letters = word.len();   // len() counts bytes (one per letter here)
            (word, letters)   // give the word back, together with its length
        });
        handles.push(handle);
    }
    for handle in handles {
        let (word, letters) = handle.join().unwrap();
        println!("{word}: {letters} bytes");
    }
}

// Output:
// alpha: 5 bytes
// beta: 4 bytes
// gamma: 5 bytes

use std::thread;

fn main() {
    let numbers = vec![1, 2, 3, 4, 5, 6];
    let (left, right) = numbers.split_at(3);   // two slices of the same Vec, no copying
    let (a, b) = thread::scope(|s| {
        let first = s.spawn(|| {
            let sum: i32 = left.iter().sum();
            sum
        });
        let second = s.spawn(|| {
            let sum: i32 = right.iter().sum();
            sum
        });
        (first.join().unwrap(), second.join().unwrap())
    });
    println!("left = {a}, right = {b}");
    println!("total = {}", a + b);
}

// Output:
// left = 6, right = 15
// total = 21

