use std::thread;

fn main() {
    let mut handles = Vec::new();
    for n in 1..=3 {
        handles.push(thread::spawn(move || n * n));
    }
    let mut results = Vec::new();
    for handle in handles {
        results.push(handle.join().unwrap());
    }
    println!("{:?}", results);
}
